query:
query getDimensionsV2(
  $dmUri: String!
  $filter: Filter
  $pagination: Pagination!
  $orderInput: OrderInput!
) {
  dimensionsV2(
    dmUri: $dmUri
    filter: $filter
    pagination: $pagination
    orderInput: $orderInput
  ) {
    totalSize
    dimensions {
      name
      technologyScore
      sentimentScore
    }
  }
}
